            "have hns : exists k. n = S k",
            "specialize nonzero_is_succ n", "apply nonzero_is_succ", "exact hn",
            "have hbez : exists xp yp xn yn. m * xp + n * yp = 1 + (m * xn + n * yn)",
            "specialize coprime_balanced_bezout m", "specialize coprime_balanced_bezout n",
