            "have hbl : exists u v. n * x3 + m * u = (1 + n * x5) + m * v",
            "specialize bezout_mod_left m", "specialize bezout_mod_left n",
            "specialize bezout_mod_left x2", "specialize bezout_mod_left x3",
            "specialize bezout_mod_left x4", "specialize bezout_mod_left x5",
            "apply bezout_mod_left", "exact hbez_witness_witness_witness_witness",
            "have hbr : exists u v. m * x2 + n * u = (1 + m * x4) + n * v",
