            "have hcodes : exists z2. forall i a. (exists h. h + i = S k) -> ((exists h. h + S a = S ((S i) * c)) /\\ exists q. b = q * S ((S i) * c) + a) -> exists u v. z2 + S ((S i) * c) * u = a + S ((S i) * c) * v",
