            "specialize beta_crt_prefix_congruence_step P", "specialize beta_crt_prefix_congruence_step z",
            "apply beta_crt_prefix_congruence_step", "exact hkN", "exact hP", "exact hdiv", "exact hcong", "exact hfuture",
            "cases hcodes", "cases hproduct", "cases hproduct_right",
            "exists x", "split", "exact hproduct_left", "split", "exact hproduct_right_left",
            "split", "exact hcodes_witness", "exact hproduct_right_right",
