                     'intro hn0',
                     'intro hn1',
                     'have hgreat : exists p. (((~(p = 1) /\\ forall a d. p = a * d -> a = 1 \\/ d '
                     '= 1) /\\ (exists k. n = p * k)) /\\ forall r. ((~(r = 1) /\\ forall a d. r = '
                     'a * d -> a = 1 \\/ d = 1) /\\ (exists k. n = r * k)) -> (exists h. h + r = '
                     'p))',
