                       '= S ((S i) * c)) /\\ exists w. b = w * S ((S i) * c) + p) /\\ (((exists h. '
                       'h + S q = S ((S S i) * c)) /\\ exists w. b = w * S ((S S i) * c) + q) /\\ '
                       '(exists h. h + p = q)))) -> (exists u v. (((exists h. h + S 1 = S ((S 0) * '
                       'v)) /\\ exists w. u = w * S ((S 0) * v) + 1) /\\ (((exists h. h + S n = S '
