                       '+ S i = l) -> exists p. (((exists h. h + S p = S ((S i) * c)) /\\ exists '
                       'w. b = w * S ((S i) * c) + p) /\\ (~(p = 1) /\\ forall a d. p = a * d -> a '
                       '= 1 \\/ d = 1))) /\\ ((forall i. (exists h. h + S S i = l) -> exists p q. '
