# Strict-HA number-theory campaign tranche 01. These factories were first
# closed and mutation-audited in isolation. Their order is part of the public
# dependency ladder: canonical remainder, the congruence bridge, the bounded
# uniqueness point, and finally the exact modular-inverse criterion.
HA_CANONICAL_REMAINDER_THEOREMS: tuple[TheoremSpec, ...] = (
    make_ha_canonical_remainder_candidate_theorems(TheoremSpec)
)
HA_CANONICAL_CONGRUENCE_THEOREMS: tuple[TheoremSpec, ...] = (
    make_ha_canonical_congruence_candidate_theorems(TheoremSpec)
)
HA_BOUNDED_MOD_INVERSE_UNIQUENESS_THEOREMS: tuple[TheoremSpec, ...] = tuple(
    spec
    for spec in make_wilson_inverse_point_candidate_theorems(TheoremSpec)
    if spec.name == "bounded_mod_inverse_unique"
)
if len(HA_BOUNDED_MOD_INVERSE_UNIQUENESS_THEOREMS) != 1:
    raise LibraryError("expected exactly one bounded modular-inverse uniqueness theorem")
HA_MODULAR_INVERSE_THEOREMS: tuple[TheoremSpec, ...] = (
    make_ha_modular_inverse_candidate_theorems(TheoremSpec)
)
HA_NUMBER_THEORY_TRANCHE01_THEOREMS: tuple[TheoremSpec, ...] = (
    *HA_CANONICAL_REMAINDER_THEOREMS,
    *HA_CANONICAL_CONGRUENCE_THEOREMS,
    *HA_BOUNDED_MOD_INVERSE_UNIQUENESS_THEOREMS,
    *HA_MODULAR_INVERSE_THEOREMS,
)
THEOREMS = _merge_compatible_theorems(
    THEOREMS,
    HA_NUMBER_THEORY_TRANCHE01_THEOREMS,
)


def names() -> tuple[str, ...]:
    """Return canonical theorem names in ladder order."""

    return tuple(spec.name for spec in THEOREMS)


def get(name: str) -> TheoremSpec | None:
    """Look up a theorem by its exact or case-folded canonical name."""

    if not isinstance(name, str):
        return None
    wanted = name.strip().casefold()
    return next((spec for spec in THEOREMS if spec.name.casefold() == wanted), None)


def _validated_specs() -> dict[str, TheoremSpec]:
    result: dict[str, TheoremSpec] = {}
    for spec in THEOREMS:
        if not spec.name or spec.name != spec.name.strip() or any(c.isspace() for c in spec.name):
            raise LibraryError("library theorem names must be non-empty single words")
        if spec.name in result:
            raise LibraryError(f"duplicate library theorem {spec.name!r}")
        _closed_formula(spec.statement)
        if not spec.script:
            raise LibraryError(f"library theorem {spec.name!r} needs a tactic script")
        for dependency in spec.dependencies:
            if dependency not in result:
                raise LibraryError(
                    f"theorem {spec.name!r} depends on unavailable earlier theorem "
                    f"{dependency!r}"
                )
        result[spec.name] = spec
    return result


@lru_cache(maxsize=1)
def _specs_by_name() -> dict[str, TheoremSpec]:
    return _validated_specs()


def replay_target(spec: TheoremSpec) -> Formula:
    """Return the dependency-curried goal replayed by ``spec.script``."""

    table = _specs_by_name()
    target = _closed_formula(spec.statement)
    for dependency in reversed(spec.dependencies):
        target = Imp(_closed_formula(table[dependency].statement), target)
    return target


@lru_cache(maxsize=None)
def replay(name: str) -> CheckedTheorem:
    """Replay one entry and independently check its closed final certificate."""

    spec = _specs_by_name().get(name)
    if spec is None:
        raise LibraryError(f"unknown library theorem {name!r}")

    target = replay_target(spec)
    state = start(target)
    for dependency in spec.dependencies:
        state = apply_tactic(state, "intro", dependency)
    for command in spec.script:
        tactic, args = _primitive(command)
        state = apply_tactic(state, tactic, args)
    certificate = checked_final(state, target)

    # Peel every generated dependency introduction. Then package the body in
    # nested, self-contained Cut nodes from the newest dependency outward.
    # Each dependency certificate is checked once at its Cut node; body uses
    # remain ordinary hypotheses and are never capture-sensitive substitutions.
    closed = certificate
    dependency_proofs = tuple(replay(item).certificate for item in spec.dependencies)
    for dependency in spec.dependencies:
        if type(closed) is not ImpIntro:
            raise LibraryError(
                f"replay for {spec.name!r} did not expose dependency {dependency!r}"
            )
        closed = closed.body
    formula = _closed_formula(spec.statement)
    dependency_formulas = tuple(
        _closed_formula(_specs_by_name()[item].statement)
        for item in spec.dependencies
    )
    for dependency_formula, dependency_proof in reversed(
        tuple(zip(dependency_formulas, dependency_proofs, strict=True))
    ):
        closed = Cut(dependency_formula, formula, dependency_proof, closed)

    if not check((), closed, formula):
        raise LibraryError(
            f"the independent kernel rejected library theorem {spec.name!r}"
        )
    return CheckedTheorem(spec, formula, closed, proof_size(closed))


def replay_all() -> tuple[CheckedTheorem, ...]:
    """Replay the entire ladder in its deterministic dependency order."""

    return tuple(replay(spec.name) for spec in THEOREMS)


